package com.haolin.vontlocal;
import android.app.*;import android.content.*;import android.os.*;import android.graphics.*;import android.graphics.drawable.*;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.util.*;import java.util.concurrent.atomic.*;

/** Emulator-only fixtures. This class is excluded from the production APK. */
public class UiAcceptance extends Instrumentation {
    JSONObject report=new JSONObject();JSONArray checks=new JSONArray();int count;File folder;Activity active;String runId;
    interface Work<T>{T call()throws Exception;}
    <T>T main(Work<T> work)throws Exception{AtomicReference<T> r=new AtomicReference<>();AtomicReference<Exception> e=new AtomicReference<>();runOnMainSync(()->{try{r.set(work.call());}catch(Exception x){e.set(x);}});if(e.get()!=null)throw e.get();return r.get();}
    void check(boolean result,String label)throws Exception{count++;checks.put(new JSONObject().put("label",label).put("passed",result));if(!result)throw new IOException(label);}
    @Override public void onCreate(Bundle args){runId=args.getString("runId","");start();}
    Context context(){return getTargetContext();}
    Activity open(Class<?> type,String... extras)throws Exception{Intent i=new Intent(context(),type).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);for(int j=0;j<extras.length;j+=2)i.putExtra(extras[j],extras[j+1]);Activity a=startActivitySync(i);active=a;waitForIdleSync();SystemClock.sleep(350);return a;}
    void finishActive()throws Exception{if(active!=null){Activity a=active;main(()->{a.finish();return true;});active=null;waitForIdleSync();}}
    void screenshot(String name)throws Exception{waitForIdleSync();SystemClock.sleep(250);Bitmap b=getUiAutomation().takeScreenshot();if(b==null)throw new IOException("No screenshot");try(FileOutputStream out=new FileOutputStream(new File(folder,name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}
    List<View> nodes(View root){List<View> values=new ArrayList<>();values.add(root);if(root instanceof ViewGroup)for(int i=0;i<((ViewGroup)root).getChildCount();i++)values.addAll(nodes(((ViewGroup)root).getChildAt(i)));return values;}
    boolean text(Activity a,String expected){for(View v:nodes(a.getWindow().getDecorView()))if(v instanceof TextView&&((TextView)v).getText().toString().contains(expected))return true;return false;}
    void fixtureDefaults(){context().getSharedPreferences("scene-presets-v1",0).edit().clear().commit();context().getSharedPreferences("sleep-settings-v1",0).edit().putInt("warm1",17).putInt("warm2",23).putInt("brightness",10).putInt("temperature",3000).putInt("minutes",27).commit();}
    JSONObject waitStatus(String action,long after)throws Exception{long end=SystemClock.elapsedRealtime()+8000;while(SystemClock.elapsedRealtime()<end){JSONObject s=LinkStore.status(context());if(s.optLong("startedAtEpochMs")>=after&&s.optString("action").equals(action)&&s.optBoolean("completed"))return s;SystemClock.sleep(100);}throw new IOException("No fresh offline service result for "+action);}
    void offlineServiceChecks()throws Exception{
        check(!new File(context().getFilesDir(),ScreenbarClient.SEALED).exists(),"offline simulator has no real connection credential");
        for(String id:SceneStore.IDS){long started=System.currentTimeMillis();main(()->LinkService.start(context(),id,"emulator-offline-test",false));JSONObject s=waitStatus(id,started);check(s.getJSONObject("vont").getString("status").equals("failed")&&s.getJSONObject("screenbar").getString("status").equals("failed"),"offline scene must not claim success: "+id);check(LinkStore.plan(context()).optLong("endEpochSeconds")==0,"offline scene did not arm a timer: "+id);}
        long started=System.currentTimeMillis();main(()->{LinkService.start(context(),"bed","emulator-offline-test",false);LinkService.start(context(),"work","emulator-offline-test",false);return true;});JSONObject work=waitStatus("work",started);check(work.optString("action").equals("work"),"new scene supersedes prior bed request");
        started=System.currentTimeMillis();main(()->{LinkService.start(context(),"bed","emulator-offline-test",false);LinkService.start(context(),"off","emulator-offline-test",false);LinkService.start(context(),"wind_down","emulator-offline-test",false);return true;});JSONObject off=waitStatus("off",started);SystemClock.sleep(250);check(LinkStore.status(context()).optString("requestId").equals(off.optString("requestId")),"all-off cannot be displaced by a queued scene");
        check(!LocalHub.busy,"offline service releases operation lock");
        ScreenbarClient.atomic(new File(context().getFilesDir(),LinkStore.STATUS),"{}".getBytes("UTF-8"));ScreenbarClient.atomic(new File(context().getFilesDir(),LinkStore.PLAN),"{}".getBytes("UTF-8"));LinkWidget.updateAll(context());
    }
    void putFixtures()throws Exception{
        LocalHub hub=main(()->LocalHub.get(context()));
        File f=new File(context().getFilesDir(),"preview-vont.json");if(f.exists()){JSONObject record=new JSONObject(new String(ScreenbarClient.readBytes(f),"UTF-8"));record.put("alias","Vont 双灯");main(()->{hub.store.devices.put(LinkPolicy.VONT,record);hub.store.save();return true;});}
    }
    void widgetPreview(boolean wide)throws Exception{HomeActivity home=(HomeActivity)open(HomeActivity.class);int width=wide?340:172,height=wide?188:160;main(()->{Ui u=new Ui(home);LinearLayout root=u.root(home);root.setPadding(u.dp(home,20),u.dp(home,20),u.dp(home,20),0);u.text(root,wide?"桌面组件 · 宽版":"桌面组件 · 紧凑版",22);u.hint(root,"模拟器渲染预览，不代表真实设备在线");View widget=LinkWidget.views(home,wide).apply(home,root);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(u.dp(home,width),u.dp(home,height));lp.topMargin=u.dp(home,20);root.addView(widget,lp);return true;});waitForIdleSync();
        main(()->{for(int id:new int[]{R.id.widget_work,R.id.widget_wind_down,R.id.widget_sleep,R.id.widget_off}){View v=home.findViewById(id);check(v!=null&&v.getWidth()>0&&v.getHeight()>=Ui.dp(home,48),"widget "+(wide?"wide":"compact")+" target "+id);check(v.hasOnClickListeners(),"widget clickable "+id);}return true;});main(()->{for(View v:nodes(home.findViewById(R.id.widget_root)))if(v instanceof TextView){TextView t=(TextView)v;check(t.getLayout()!=null&&t.getLayout().getHeight()+t.getCompoundPaddingTop()+t.getCompoundPaddingBottom()<=t.getHeight(),"widget text not vertically clipped: "+t.getText());}return true;});screenshot((wide?"widget-wide-":"widget-compact-")+Ui.appearance(context()));finishActive();}
    void screenbarPreview(String tab,String settings)throws Exception{ScreenbarActivity a=(ScreenbarActivity)open(ScreenbarActivity.class,"entryTab",tab);main(()->{JSONObject props=new JSONObject();int[][] keys=ScreenbarClient.KEYS;for(int[] k:keys){Object v=0;switch(k[0]+"."+k[1]){case "2.1":case "2.4":case "3.1":case "3.8":v=true;break;case "3.4":case "3.6":case "3.18":v=false;break;case "2.2":v=70;break;case "2.3":v=3500;break;case "3.2":v=30;break;case "3.16":v=45;break;case "3.17":v=10;break;case "3.27":v="preview-remote";break;default:if(k[0]==3&&k[1]>=19&&k[1]<=26)v=k[1]%2==1?50:4000;}props.put(k[0]+"."+k[1],v);}
        a.state=new ScreenbarClient.State(props,new JSONObject().put("model","yeelink.light.lamp22").put("firmware","界面预览").put("hardware","ESP32"),System.currentTimeMillis());a.fresh=true;a.settingsPage=settings;a.showTab();a.summary.setText("界面预览 · 70% · 3500K");a.status.setText("模拟器测试状态，未连接真实灯具");if(a.lastNotice!=null)a.lastNotice.cancel();return true;});
        check(text(a,"界面预览"),"screenbar fixture clearly labeled");if("模式".equals(tab)){main(()->{a.editMode(2,"63","3200");a.showTab();return true;});check(main(()->a.modeDialog!=null&&a.modeDialog.isShowing()&&a.modeB.getText().toString().equals("63")&&a.modeK.getText().toString().equals("3200")),"mode draft survives parent refresh");main(()->{a.modeDialog.dismiss();return true;});}
        screenshot("screenbar-"+("设置".equals(tab)?settings:"模式".equals(tab)?"modes":"light"));finishActive();
    }
    @Override public void onStart(){int result=0;try{
        if(!(Build.HARDWARE.contains("ranchu")||Build.HARDWARE.contains("goldfish")))throw new IOException("Emulator-only tests must never run on a phone");
        folder=new File(context().getFilesDir(),"ui-acceptance");folder.mkdirs();report.put("runId",runId).put("startedAtEpochMs",System.currentTimeMillis()).put("fontScale",context().getResources().getConfiguration().fontScale).put("scope","Emulator fixtures and native UI only; no physical lamps, MiHome or timing completion verified");
        String before=LinkStore.status(context()).toString();fixtureDefaults();SceneStore.ensure(context());LinkPolicy.Settings w=SceneStore.settings(context(),"work"),n=SceneStore.settings(context(),"wind_down"),b=SceneStore.settings(context(),"bed");check(w.brightness==100&&w.temperature==4500,"work defaults");check(n.brightness==70&&n.temperature==3500,"wind-down defaults");check(b.brightness==1&&b.temperature==2700&&b.warm1==17&&b.warm2==23&&b.minutes==27,"migration keeps warm channels and duration, seeds requested bed minimum");
        SceneStore.save(context(),"work",new LinkPolicy.Settings(1,1,83,4100,15));SceneStore.ensure(context());check(SceneStore.settings(context(),"work").brightness==83,"ensure never resets a saved preset");check(SceneStore.settings(context(),"wind_down").brightness==70,"saving one scene leaves others unchanged");check(before.equals(LinkStore.status(context()).toString()),"preset migration and save do not start a control request");
        SceneStore.save(context(),"work",new LinkPolicy.Settings(10,10,100,4500,15));SceneStore.save(context(),"wind_down",new LinkPolicy.Settings(10,10,70,3500,15));SceneStore.save(context(),"bed",new LinkPolicy.Settings(10,10,1,2700,15));putFixtures();offlineServiceChecks();
        for(String theme:new String[]{"light","dark"}){context().getSharedPreferences("appearance-v1",0).edit().putString("theme",theme).commit();HomeActivity a=(HomeActivity)open(HomeActivity.class);check(text(a,"办公")&&text(a,"睡前")&&text(a,"床上"),"home scene entries "+theme);screenshot("home-"+theme);finishActive();SleepActivity editor=(SleepActivity)open(SleepActivity.class,"sceneId","bed");check(main(()->editor.brightness.getText().toString().equals("1")&&editor.minutes.getText().toString().equals("15")),"bed editor settings "+theme);screenshot("bed-editor-"+theme);finishActive();}
        context().getSharedPreferences("appearance-v1",0).edit().putString("theme","light").commit();
        SleepActivity keyboard=(SleepActivity)open(SleepActivity.class,"sceneId","bed");main(()->{keyboard.brightness.requestFocus();((android.view.inputmethod.InputMethodManager)keyboard.getSystemService(Context.INPUT_METHOD_SERVICE)).showSoftInput(keyboard.brightness,android.view.inputmethod.InputMethodManager.SHOW_IMPLICIT);return true;});SystemClock.sleep(900);
        check(main(()->keyboard.getWindow().getDecorView().getRootWindowInsets().isVisible(WindowInsets.Type.ime())),"keyboard displayed for editor test");
        main(()->{Rect frame=new Rect();keyboard.getWindow().getDecorView().getWindowVisibleDisplayFrame(frame);for(View v:nodes(keyboard.getWindow().getDecorView()))if(v instanceof Button&&((Button)v).getText().toString().equals("保存床上场景")){int[] xy=new int[2];v.getLocationOnScreen(xy);check(xy[1]+v.getHeight()<=frame.bottom,"save action remains above keyboard");}return true;});screenshot("bed-editor-keyboard");main(()->{((android.view.inputmethod.InputMethodManager)keyboard.getSystemService(Context.INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(keyboard.brightness.getWindowToken(),0);return true;});finishActive();
        widgetPreview(true);widgetPreview(false);context().getSharedPreferences("appearance-v1",0).edit().putString("theme","dark").commit();widgetPreview(true);widgetPreview(false);context().getSharedPreferences("appearance-v1",0).edit().putString("theme","light").commit();
        screenbarPreview("调节","计时");screenbarPreview("模式","计时");for(String tab:new String[]{"计时","通电","遥控器","资料"})screenbarPreview("设置",tab);
        MainActivity vont=(MainActivity)open(MainActivity.class,"entryTab","调节");main(()->{vont.connection.setText("模拟器预览 · 已保存的 Vont 资料，未连接真实灯具");return true;});screenshot("vont-light");for(String tab:new String[]{"分段","场景","设置"}){main(()->{vont.switchTab(tab);return true;});screenshot("vont-"+("分段".equals(tab)?"segments":"场景".equals(tab)?"scenes":"settings"));}finishActive();
        SettingsActivity settings=(SettingsActivity)open(SettingsActivity.class);screenshot("settings-light");finishActive();
        Drawable icon=context().getDrawable(R.mipmap.ic_launcher);Bitmap bitmap=Bitmap.createBitmap(512,512,Bitmap.Config.ARGB_8888);icon.setBounds(0,0,512,512);icon.draw(new Canvas(bitmap));try(FileOutputStream out=new FileOutputStream(new File(folder,"app-icon.png"))){bitmap.compress(Bitmap.CompressFormat.PNG,100,out);}bitmap.recycle();
        report.put("status","passed").put("checks",checks).put("checkCount",count).put("emulatorHardware",Build.HARDWARE).put("realDeviceDeferredByUser",true);
    }catch(Exception e){result=1;try{report.put("status","failed").put("error",e.toString()).put("checks",checks);}catch(Exception ignored){}}
        try{ScreenbarClient.atomic(new File(context().getFilesDir(),"emulator-ui-report.json"),report.toString(2).getBytes("UTF-8"));}catch(Exception e){result=1;}
        Bundle out=new Bundle();out.putString("result",report.toString());finish(result,out);
    }
}
